3	import { revalidatePath } from "next/cache";
4	import { db } from "@/lib/db";
5	import { requireAdmin } from "@/lib/auth";
6	import { createInvoice, type LineItem } from "@/lib/invoices";
7	
8	async function audit(userId: string | null, action: string, detail?: string) {
9	  await db.auditLog.create({ data: { userId, action, detail } });
10	}
11	
12	/**
13	 * Admin: generate an OPEN invoice for a server's current plan (one billing
14	 * period). Does not charge the wallet — it records what is owed; the wallet
15	 * ledger and invoices are complementary records.
16	 */
17	export async function generateInvoiceForServer(serverId: string) {
18	  const admin = await requireAdmin();
19	  const server = await db.server.findUnique({
20	    where: { id: serverId },
21	    include: { plan: true, user: { select: { id: true, email: true } } },
22	  });
23	  if (!server) throw new Error("Server not found");
24	  if (server.isFree) throw new Error("Free servers are not billed");
25	
26	  const now = new Date();
27	  const periodEnd = new Date(now.getTime() + 30 * 86400_000);
28	  const line: LineItem = {
29	    description: `${server.plan.name} — ${server.hostname}`,
30	    qty: 1,
31	    unitCents: server.plan.priceCents,
32	    amountCents: server.plan.priceCents,
33	  };
34	
35	  const invoice = await createInvoice({
36	    userId: server.userId,
37	    description: `${server.plan.name} plan · ${server.hostname}`,
38	    lineItems: [line],
39	    status: "OPEN",
40	    period: { start: now, end: periodEnd },
41	  });
42	
43	  await audit(
44	    admin.id,
45	    "invoice.generate",
46	    `#${invoice.number} for ${server.hostname} (${server.user.email})`
47	  );
48	  revalidatePath("/admin/invoices");
49	  revalidatePath("/dashboard/invoices");
50	  return { id: invoice.id, number: invoice.number };
51	}
52	
53	/** Admin: void an open/unpaid invoice. */
54	export async function voidInvoice(id: string) {
55	  const admin = await requireAdmin();
56	  const invoice = await db.invoice.findUnique({ where: { id } });
57	  if (!invoice) throw new Error("Invoice not found");
58	  if (invoice.status === "PAID") throw new Error("Paid invoices cannot be voided — refund instead");
59	  if (invoice.status === "VOID") return { ok: true };
60	
61	  await db.invoice.update({ where: { id }, data: { status: "VOID", paidAt: null } });
62	  await audit(admin.id, "invoice.void", `#${invoice.number}`);
63	  revalidatePath("/admin/invoices");
64	  revalidatePath(`/admin/invoices/${id}`);
65	  revalidatePath("/dashboard/invoices");
66	  return { ok: true };
67	}
68	
69	/** Admin: mark an invoice paid. */
70	export async function markInvoicePaid(id: string) {
71	  const admin = await requireAdmin();
72	  const invoice = await db.invoice.findUnique({
73	    where: { id },
74	    // Pull the invoice owner's saved card so we can snapshot the paying method
75	    // onto the invoice in the same update that flips it to PAID.
76	    include: { user: { select: { cardBrand: true, cardLast4: true } } },
77	  });
78	  if (!invoice) throw new Error("Invoice not found");
79	  if (invoice.status === "VOID") throw new Error("Void invoices cannot be marked paid");
80	  if (invoice.status === "PAID") return { ok: true };
81	
82	  await db.invoice.update({
83	    where: { id },
84	    data: {
85	      status: "PAID",
86	      paidAt: new Date(),
87	      // Null-safe: a user with no saved card leaves these null.
88	      paidBrand: invoice.user.cardBrand ?? null,
89	      paidLast4: invoice.user.cardLast4 ?? null,
90	    },
91	  });
92	  await audit(admin.id, "invoice.mark_paid", `#${invoice.number}`);
93	  revalidatePath("/admin/invoices");
94	  revalidatePath(`/admin/invoices/${id}`);
95	  revalidatePath("/dashboard/invoices");
96	  return { ok: true };
97	}
98	
99	/**
100	 * Admin: generate OPEN invoices for every paid, active server that has no
101	 * invoice yet. Best-effort backfill — safe to run repeatedly.
102	 */
103	export async function regenerateMissingInvoices() {
104	  const admin = await requireAdmin();
105	  const servers = await db.server.findMany({
106	    where: { isFree: false, status: { not: "DELETING" } },
107	    include: { plan: true },
108	  });
109	
110	  let created = 0;
111	  for (const server of servers) {
112	    const existing = await db.invoice.count({
113	      where: {
114	        userId: server.userId,
115	        description: { contains: server.hostname },
116	        status: { not: "VOID" },
117	      },
118	    });
119	    if (existing > 0) continue;
120	    const now = new Date();
121	    await createInvoice({
122	      userId: server.userId,
123	      description: `${server.plan.name} plan · ${server.hostname}`,
124	      lineItems: [
125	        {
126	          description: `${server.plan.name} — ${server.hostname}`,
127	          qty: 1,
128	          unitCents: server.plan.priceCents,
129	          amountCents: server.plan.priceCents,
130	        },
131	      ],
132	      status: "OPEN",
133	      period: { start: now, end: new Date(now.getTime() + 30 * 86400_000) },
134	    });
135	    created++;
136	  }
137	
138	  await audit(admin.id, "invoice.regenerate_missing", `${created} created`);
139	  revalidatePath("/admin/invoices");
140	  revalidatePath("/dashboard/invoices");
141	  return { created };
142	}
