3	import { useActionState, useState } from "react";
4	import { topUp } from "@/lib/actions";
5	import { Badge } from "@/components/ui/primitives";
6	import { AddFundsPaymentModal } from "@/components/customer/AddFundsPaymentModal";
7	
8	const PRESETS = [10, 25, 50, 100];
9	
10	function DemoTopUp() {
11	  const [state, action, pending] = useActionState(topUp, {});
12	  // CONTROLLED, deliberately. React 19 resets uncontrolled fields on every
13	  // `<form action={fn}>` submit — including a REJECTED one. `topUp` returns
14	  // `{error}`, so an uncontrolled amount snapped back to the default while the
15	  // error pointed at a figure no longer on screen. Same reset class as
16	  // AutoRecharge.tsx.
17	  const [amount, setAmount] = useState("25");
18	  return (
19	    <div>
20	      <div className="mb-3 flex items-center gap-2">
21	        <Badge tone="amber">demo gateway</Badge>
22	        <span className="text-xs text-slate-500">
23	          Card payments are not configured — funds are credited instantly for testing.
24	        </span>
25	      </div>
26	      <form action={action} className="flex items-end gap-3">
27	        <div>
28	          <label className="label">Amount (USD)</label>
29	          <input
30	            className="input w-36"
31	            name="amount"
32	            type="number"
33	            min={1}
34	            max={1000}
35	            step="0.01"
36	            value={amount}
37	            onChange={(e) => setAmount(e.target.value)}
38	          />
39	        </div>
40	        <button className="btn-primary" disabled={pending}>
41	          {pending ? "Adding…" : "Add funds"}
42	        </button>
43	        {state?.error && <span className="text-sm text-red-400">{state.error}</span>}
44	      </form>
45	    </div>
46	  );
47	}
