/** Renders inside `<CheckoutElementsProvider>` — the only place `useCheckoutElements()` is valid. */
function TopUpPaymentForm({ amountCents }: { amountCents: number }) {
  const checkoutState = useCheckoutElements();
  const checkoutActions = checkoutState.type === "success" ? checkoutState.checkout : undefined;
  const [confirming, setConfirming] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [expressPayAvailable, setExpressPayAvailable] = useState(false);

  async function payWithCard() {
    if (!checkoutActions) return;
    setError(null);
    setConfirming(true);
    try {
      // Always save the card — the wallet is what the auto-renewal sweep
      // draws from, so a customer who tops up is exactly who benefits from
      // having a chargeable card on file (same default as PaymentStep).
      const result = await checkoutActions.confirm({ savePaymentMethod: true });
      if (result.type === "error") setError(result.error.message ?? "Your card was declined. Please try another payment method.");
      // On success Stripe navigates the browser to the session's return_url —
      // the same /api/stripe/confirm route every other payment on this
      // platform uses. Nothing else to do here.
    } catch {
      setError("Something went wrong confirming your payment. Please try again.");
    } finally {
      setConfirming(false);
    }
  }

  return (
    <div className="space-y-4">
      <div>
        <label className="mb-1.5 flex items-center gap-1.5 text-xs font-medium text-slate-400">
          <LockIcon /> Card details
        </label>
        <div className="rounded-lg border border-white/[0.08] bg-white/[0.02] p-3">
          <PaymentElement
            options={{
              layout: "tabs",
              fields: { billingDetails: { name: "auto" } },
              paymentMethodOrder: ["card"],
            }}
          />
        </div>
      </div>

      {/* ONE ExpressCheckoutElement, always mounted, showing whichever
          wallets the browser/device supports — same reasoning as
          PaymentStep.tsx's block: visibility (not mounting) is gated on
          onReady so a static, non-interactive row never appears. */}
      <div className={expressPayAvailable ? "rounded-xl border border-white/[0.07] bg-white/[0.02] p-4" : "hidden"}>
        <p className="mb-3 text-xs font-medium text-slate-400">Express checkout</p>
        <ExpressCheckoutElement
          options={{
            buttonHeight: undefined,
            buttonTheme: undefined,
            buttonType: undefined,
            layout: undefined,
            paymentMethodOrder: undefined,
            paymentMethods: { googlePay: "auto", applePay: "auto", link: "never", paypal: "never", amazonPay: "never" },
          }}
          onReady={(e) =>
            setExpressPayAvailable(!!(e.availablePaymentMethods?.googlePay || e.availablePaymentMethods?.applePay))
          }
          onConfirm={async (event) => {
            if (!checkoutActions) return;
            setError(null);
            const result = await checkoutActions.confirm({ expressCheckoutConfirmEvent: event });
            if (result.type === "error") setError(result.error.message ?? "Payment failed.");
          }}
        />
      </div>

      {error && <p className="rounded-lg border border-red-500/25 bg-red-500/10 px-3 py-2 text-xs text-red-300">{error}</p>}

      <button
        type="button"
        onClick={payWithCard}
        disabled={confirming || !checkoutActions?.canConfirm}
        className="btn-deploy w-full py-3 text-sm"
      >
        <LockIcon className="h-4 w-4" />
        {confirming ? "Processing…" : `Pay Securely ${money(amountCents)}`}
        {!confirming && <span className="dep-arrow">→</span>}
      </button>
      <p className="text-center text-[11px] text-slate-500">
        Card numbers are entered directly into Stripe&apos;s secure fields — they never touch Nxeon&apos;s servers.
      </p>
    </div>
  );
}

export function AddFundsPaymentModal({
  clientSecret,
  publishableKey,
  amountCents,
  onClose,
}: {
  clientSecret: string;
  publishableKey: string;
  amountCents: number;
  onClose: () => void;
}) {
  const stripePromise = useMemo(() => stripeFor(publishableKey), [publishableKey]);
  const themeKey = useStripeThemeKey();

  // Portaled to document.body — the Billing page's <main> carries a
  // `transform` from its own entrance animation (animate-fade-up), and per
  // the CSS spec ANY transform on an ancestor (even the identity matrix a
  // finished animation settles on) creates a new containing block for
  // `position: fixed` descendants. Left in place, `fixed inset-0` here
  // resolved against that ancestor's box instead of the viewport, clipping
  // most of the modal off-screen (real bug: a customer saw only the bottom
  // sliver of the payment form). Same fix HeardAboutUsPrompt.tsx already
  // uses for the identical reason.
  return createPortal(
    <div
      className="fixed inset-0 z-[100] flex items-start justify-center overflow-y-auto bg-black/60 p-4 backdrop-blur-sm sm:p-8"
      role="dialog"
      aria-modal="true"
      aria-label="Add funds"
    >
      <div className="relative my-auto w-full max-w-md rounded-2xl border border-white/10 bg-navy-950 p-5 shadow-2xl">
        <div className="flex items-center justify-between pb-4">
          <div>
            <p className="text-sm font-semibold text-slate-100">Add funds</p>
            <p className="text-xs text-slate-500">{money(amountCents)} added to your Nxeon wallet</p>
          </div>
          <button
            type="button"
            onClick={onClose}
            aria-label="Close"
            className="rounded-lg px-2 py-1 text-slate-400 transition hover:bg-white/5 hover:text-white"
          >
            ✕
          </button>
        </div>

        <CheckoutElementsProvider
          key={themeKey}
          stripe={stripePromise}
          options={{ clientSecret, elementsOptions: { appearance: currentStripeAppearance(), fonts: STRIPE_FONTS } }}
        >
          <TopUpPaymentForm amountCents={amountCents} />
        </CheckoutElementsProvider>
      </div>
    </div>,
    document.body,
  );
}
