119	  const value = typeof session.amount_total === "number" ? session.amount_total / 100 : 0;
120	  if (!(value > 0)) return redirect; // free / zero-charge order — nothing to report
121	  const currency = (session.currency ?? "usd").toUpperCase();
122	  // Best-effort match signals from the request: the Meta _fbc/_fbp cookies + UA/IP.
123	  // Wrapped so the webhook path (no browser request scope) simply sends without them.
124	  let fbc: string | undefined, fbp: string | undefined, userAgent: string | undefined, clientIp: string | undefined;
125	  try {
126	    const [ck, h] = await Promise.all([cookies(), headers()]);
127	    fbc = ck.get("_fbc")?.value || undefined;
128	    fbp = ck.get("_fbp")?.value || undefined;
129	    userAgent = h.get("user-agent") ?? undefined;
130	    clientIp = (h.get("x-forwarded-for")?.split(",")[0] ?? "").trim() || undefined;
131	  } catch {
132	    /* no request scope (webhook) — send without cookie/UA signals */
133	  }
134	  const { eventId } = await sendMetaConversion({
135	    eventName: "Purchase",
136	    email,
137	    value,
138	    currency,
139	    sourceUrl: redirect,
140	    fbc,
141	    fbp,
142	    userAgent,
143	    clientIp,
144	    externalId: userId,
145	  });
