147	  // gclid — reliable where the browser gtag is not. Best-effort + idempotent (deduped
148	  // on the Stripe session id). Fires the product-specific action (vps/hosting/game/…)
149	  // AND a generic "purchase". Inert until the Ads API creds are configured.
150	  if (userId) {
151	    try {
152	      const { recordAdsConversion } = await import("./google-ads");
153	      const valueCents = Math.round(value * 100);
154	      if (prod) await recordAdsConversion({ kind: prod, userId, dedupeKey: `${prod}:${session.id}`, valueCents, currency });
155	      await recordAdsConversion({ kind: "purchase", userId, dedupeKey: `purchase:${session.id}`, valueCents, currency });
156	    } catch {
157	      /* tracking is best-effort — the order is already fulfilled */
158	    }
159	  }
160	  const params = new URLSearchParams({ purchase: "1", pv: value.toFixed(2), pc: currency, pe: eventId, ...(prod ? { prod } : {}) });
161	  return `${redirect}${redirect.includes("?") ? "&" : "?"}${params.toString()}`;
162	}
