164	/**
165	 * Credit the wallet and fulfil whatever the session was for, exactly once.
166	 * Safe to call repeatedly and concurrently from the redirect and the webhook.
167	 *
168	 * THROWS when Stripe cannot be read. That is deliberate and it is the fix for the
169	 * defect found on 2026-07-27: this function used to ask three helpers for the
170	 * session, each of which swallowed every error into `null`, so a transient Stripe
171	 * failure was indistinguishable from "no purchase metadata" and fell through to
172	 * the top-up branch below reporting `fulfilled: true`. A real order then had its
173	 * card charged with no server, no FulfilledSession row and no notification — and
174	 * because the webhook returns 200 either way, Stripe never retried it. A throw
175	 * lands the browser on `?pending=1` (see app/api/stripe/confirm) and puts the
176	 * failure in the webhook's log, which is loud; declaring it a top-up was silent.
177	 */
178	export async function fulfilCheckoutSession(sessionId: string, base = ""): Promise<FulfilResult> {
179	  // ONE retrieve, one view of the session, shared by the credit and the routing.
180	  const session = await retrieveCheckoutSession(sessionId);
181	  const purpose = classifyCheckoutSession(session);
182	  return runFulfilment(session, purpose, base, "stripe");
183	}
