185	/**
186	 * The actual dispatch, factored out of `fulfilCheckoutSession` so
187	 * `fulfilExternalPayment` (PayPal / Coinbase Commerce, below) can drive the exact
188	 * same claim/credit/provision/settle/notify logic from a SYNTHETIC session-shaped
189	 * object instead of a real Stripe retrieve. Nothing in this function's body
190	 * changed from the original `fulfilCheckoutSession` other than: (a) `sessionId` is
191	 * now read off `session.id` instead of being a separate parameter, and (b) the two
192	 * spots that are genuinely Stripe-only — crediting the wallet, and recording the
193	 * card for renewals — are gated on `provider === "stripe"`. Every claim/settle/
194	 * notify/provisioning line is untouched.
195	 */
196	async function runFulfilment(
197	  session: Stripe.Checkout.Session,
198	  purpose: CheckoutPurpose,
199	  base: string,
200	  provider: PaymentProvider,
201	): Promise<FulfilResult> {
202	  const sessionId = session.id;
203	
204	  // Nothing was paid (an abandoned session id, or one replayed before capture).
205	  // Never claim fulfilment for money that has not arrived.
206	  if (purpose.kind === "unpaid") {
207	    return { redirect: `${base}/dashboard/billing`, fulfilled: false, kind: "none" };
208	  }
209	
210	  // Crediting is separately idempotent (UNIQUE stripeSessionId on the wallet
211	  // transaction). We deliberately IGNORE its return value now — it reports who
212	  // won the credit race, which is not the same question as "has this been
213	  // fulfilled", and conflating the two was the bug. A THROW, however, is not a
214	  // race: the money has not reached the wallet, so nothing below may spend it.
215	  //
216	  // `creditCheckoutSession` itself is Stripe-specific (it types its argument as a
217	  // real `Stripe.Checkout.Session`); PayPal/Coinbase route through
218	  // `creditExternalPayment` instead, which writes the identical
219	  // WalletTransaction/User.balanceCents/notification shape but with an honest
220	  // ledger label (never "Stripe payment" for money PayPal or Coinbase moved) and
221	  // no invoice branch, since every external-payment kind reaching this function is
222	  // a purchase leg, never a bare top-up — see that function's doc comment.
223	  if (provider === "stripe") {
224	    await creditCheckoutSession(session);
225	  } else {
226	    await creditExternalPayment(session, provider);
227	  }
228	
229	  // Purchase metadata is present but cannot be trusted. Retrying will never fix
230	  // it, so claim the session and record the failure exactly like a failed order:
231	  // reconcilable, and the customer is told. What it must NEVER become is a silent
232	  // wallet top-up, which is precisely what the old `null` fall-through produced.
233	  if (purpose.kind === "unreadable") {
234	    if (await claim(sessionId, "unreadable")) {
235	      await settle(sessionId, "FAILED", purpose.detail);
236	      if (purpose.userId) await notifyStalled(purpose.userId);
237	    }
238	    return {
239	      redirect: `${base}/dashboard/billing?paid=1`,
240	      fulfilled: false,
241	      kind: "none",
242	      error: purpose.detail,
243	    };
244	  }
245	
246	  const order = purpose.kind === "order" ? purpose : null;
247	  if (order) {
248	    if (!(await claim(sessionId, "order"))) {
249	      return { redirect: `${base}/dashboard/servers`, fulfilled: false, kind: "order" };
250	    }
251	    try {
252	      const user = await db.user.findUnique({ where: { id: order.userId } });
253	      if (!user) throw new Error("user not found for paid order");
