645	  const cents = session.amount_total ?? 0;
646	  if (!userId || cents <= 0 || session.payment_status !== "paid") return false;
647	
648	  if (!isPurchaseLegSession(session.metadata)) {
649	    throw new Error(
650	      `${provider} payment ${session.id} carries no recognised purchase metadata — refusing to treat unrecognised money as a top-up`,
651	    );
652	  }
653	
654	  const label = provider === "paypal" ? "PayPal" : "Coinbase Commerce";
655	  try {
656	    await db.$transaction([
657	      db.walletTransaction.create({
658	        data: {
659	          userId,
660	          amountCents: cents,
661	          description: `${label} payment (${session.id})`,
662	          stripeSessionId: session.id,
663	        },
664	      }),
665	      db.user.update({ where: { id: userId }, data: { balanceCents: { increment: cents } } }),
666	      db.notification.create({
667	        data: {
668	          userId,
669	          title: `Payment of $${(cents / 100).toFixed(2)} received`,
670	          href: "/dashboard/billing",
671	        },
672	      }),
673	    ]);
