1422	  // read-then-write check. The confirm-redirect and the webhook can arrive
1423	  // concurrently (and /api/stripe/confirm is unauthenticated and replayable), so
1424	  // only the database can safely decide the winner. P2002 == already credited.
1425	  const ops: Prisma.PrismaPromise<unknown>[] = [
1426	    db.walletTransaction.create({
1427	      data: {
1428	        userId,
1429	        amountCents: cents,
1430	        description: `Stripe payment (${session.id})`,
1431	        stripeSessionId: session.id,
1432	      },
1433	    }),
1434	    db.user.update({ where: { id: userId }, data: { balanceCents: { increment: cents } } }),
1435	    db.notification.create({
1436	      data: {
1437	        userId,
1438	        title: `Payment of $${(cents / 100).toFixed(2)} received`,
1439	        href: "/dashboard/billing",
1440	      },
1441	    }),
1442	  ];
