1445	  let invoiceOpIndex = -1;
1446	  if (!purchaseLeg) {
1447	    // PAID invoice for the top-up. Created in the SAME guarded transaction as
1448	    // the wallet credit, so the UNIQUE(stripeSessionId) constraint that makes
1449	    // the credit idempotent also prevents a duplicate invoice on replay.
1450	    //
1451	    // A purchase leg is deliberately left undocumented HERE: the order, resize or
1452	    // disk-expansion it funds issues the one invoice for the whole purchase, and
1453	    // that document — not this one — is what the customer's card statement shows.
1454	    // If the fulfilment then fails the money stays in the wallet as an ordinary
