1461	    invoiceOpIndex = ops.length;
1462	    ops.push(
1463	      db.invoice.create({
1464	        data: invoiceCreateData({
1465	          userId,
1466	          description: "Wallet top-up",
1467	          status: "PAID",
1468	          lineItems: [
1469	            { description: "Wallet top-up", qty: 1, unitCents: cents, amountCents: cents },
1470	          ],
1471	        }),
1472	      }),
1473	    );
1474	  }
1475	  let invoiceId: string | undefined;
1476	  try {
1477	    const results = await db.$transaction(ops);
1478	    if (invoiceOpIndex >= 0) {
1479	      const created = results[invoiceOpIndex] as { id?: string } | undefined;
1480	      invoiceId = created?.id;
1481	    }
1482	  } catch (e) {
1483	    if ((e as { code?: string })?.code === "P2002") return false; // raced — already credited
