2	//
3	// Plain (non-"use server") module: exports pure helpers alongside async getters
4	// that read the `Setting` store. Safe to import from server components, server
5	// actions, the worker and (the pure parts) client components. Money is always
6	// integer cents.
7	//
8	// IMPORTANT — multi-currency here is DISPLAY ONLY. `formatMoney` swaps the symbol
9	// and code for the configured `currency` Setting; it performs NO FX conversion,
10	// so the underlying cents are unchanged. Do not use this to bill in a foreign
11	// currency. Tax helpers likewise compute a display/quote breakdown; wiring them
12	// into the actual charge path is an integration step owned by the billing flow.
13	
14	import { getSetting } from "./settings";
15	import { DEFAULT_CURRENCY } from "./currency";
16	
17	// ---------------- Currency (display only) ----------------
18	//
19	// The pure currency primitives (symbol map, formatMoney, and the DISPLAY-ONLY FX
20	// conversion helpers) now live in lib/currency.ts, which has NO server deps so it
21	// is safe in the client bundle. They are re-exported here so every existing
22	// `@/lib/tax` import site keeps working unchanged. Only `currentCurrency` stays
23	// defined here, because it reads the Setting store.
24	
25	export type { CurrencyMeta } from "./currency";
26	export {
27	  CURRENCIES,
28	  DEFAULT_CURRENCY,
29	  currencyMeta,
30	  formatMoney,
31	  ZERO_DECIMAL_CURRENCIES,
32	  DEFAULT_CURRENCY_RATES,
33	  parseRatesOverride,
34	  rateFor,
35	  convertCents,
36	  convertAndFormat,
37	} from "./currency";
38	
39	/** The configured display currency code (reads the `currency` Setting). */
40	export async function currentCurrency(): Promise<string> {
41	  const raw = (await getSetting("currency")).trim().toUpperCase();
42	  return raw || DEFAULT_CURRENCY;
43	}
44	
45	// ---------------- Tax / VAT ----------------
46	
47	export type TaxBreakdown = { net: number; tax: number; total: number };
48	
49	/**
50	 * The configured tax/VAT rate as a percent number (reads the `tax_percent` Setting).
51	 *
52	 * ⚠ THIS RATE IS NOT CHARGED TO ANYONE. `applyTaxFromSettings` has exactly one call site
53	 * — the MRR reference figure on /admin/products — and no charge path passes `taxCents` to
54	 * `invoiceCreateData`, so every `Invoice` row in the system stores `taxCents: 0` and every
55	 * rendered invoice shows Tax $0.00. QA P1-11 / DOCUMENTATION.md gap 22.
56	 *
57	 * Deliberately left that way. Starting to collect tax is a legal and business decision
58	 * (registration, rate by jurisdiction, reverse charge, invoice content requirements, and
59	 * remittance) and silently switching it on because a settings field existed would be a
60	 * far more serious error than the field being inert. What was fixed instead is the lie:
61	 * Settings → Billing now states on the control itself that the rate is display-only and
62	 * must not be relied on to collect VAT/GST.
63	 *
64	 * If tax is ever genuinely charged, the wiring is `applyTax()` at each charge site plus
65	 * `taxCents` into `invoiceCreateData` — and the note in
66	 * components/admin/settings/BillingPanel.tsx must be deleted in the same commit.
67	 */
68	export async function taxRate(): Promise<number> {
69	  const n = Number(await getSetting("tax_percent"));
70	  return Number.isFinite(n) && n > 0 ? n : 0;
71	}
72	
73	/**
74	 * Split a net (pre-tax) amount in cents into { net, tax, total }. Pure — pass the
75	 * rate (e.g. from `taxRate()`); the tax is rounded to the nearest cent. A rate of
76	 * 0 yields tax 0 and total === net.
77	 */
78	export function applyTax(cents: number, ratePercent: number = 0): TaxBreakdown {
79	  const net = Math.max(0, Math.round(Number.isFinite(cents) ? cents : 0));
80	  const rate = Number.isFinite(ratePercent) && ratePercent > 0 ? ratePercent : 0;
81	  const tax = Math.round((net * rate) / 100);
82	  return { net, tax, total: net + tax };
83	}
84	
85	/** Async convenience: read the configured rate and apply it in one call. */
86	export async function applyTaxFromSettings(cents: number): Promise<TaxBreakdown> {
87	  return applyTax(cents, await taxRate());
88	}
89	
90	// ---------------- Destination-country VAT (CHARGED, Finding 1) ----------------
91	//
92	// This is the part that is genuinely BILLED. `taxRate()` above is a single global
93	// rate; a real VAT obligation is per DESTINATION country, with a B2B reverse-charge
94	// carve-out. The rates below are standard-rate VAT/GST snapshots by ISO-3166 alpha-2
95	// country. They are conservative inputs to a charge: when we do not recognise a
96	// country we fall back to the configured `tax_percent` (0 unless the operator set
97	// one), never to a guess that could overcharge.
98	
99	/** EU-27 member states — the set the reverse-charge rule applies within. */
100	export const EU_COUNTRIES = new Set([
101	  "AT", "BE", "BG", "HR", "CY", "CZ", "DK", "EE", "FI", "FR", "DE", "GR", "HU",
102	  "IE", "IT", "LV", "LT", "LU", "MT", "NL", "PL", "PT", "RO", "SK", "SI", "ES", "SE",
103	]);
104	
105	/**
106	 * Standard-rate VAT/GST by destination country (percent). EU-27 + UK. Deliberately
107	 * the STANDARD rate only: reduced/zero rates are product-specific and cloud hosting
108	 * is a standard-rated electronically-supplied service in every jurisdiction here, so
109	 * the standard rate is the correct, conservative one to charge.
110	 */
111	export const COUNTRY_VAT_RATES: Record<string, number> = {
112	  AT: 20, BE: 21, BG: 20, HR: 25, CY: 19, CZ: 21, DK: 25, EE: 22, FI: 25.5,
113	  FR: 20, DE: 19, GR: 24, HU: 27, IE: 23, IT: 22, LV: 21, LT: 21, LU: 17,
114	  MT: 18, NL: 21, PL: 23, PT: 23, RO: 19, SK: 23, SI: 22, ES: 21, SE: 25,
115	  GB: 20,
116	};
117	
118	/** Normalise a country input to an uppercase ISO-3166 alpha-2 code, or "". */
119	export function normalizeCountry(country: string | null | undefined): string {
120	  const c = (country ?? "").trim().toUpperCase();
121	  return /^[A-Z]{2}$/.test(c) ? c : "";
122	}
123	
124	/**
125	 * Loose structural validation of an EU VAT identification number: the 2-letter
126	 * country prefix must match `country`, followed by 2–12 alphanumerics. This is NOT
127	 * a VIES lookup — it is deliberately conservative in the ONLY direction that moves
128	 * money: a malformed id fails here and the caller charges the destination consumer
129	 * rate rather than granting a 0% reverse charge it cannot stand behind.
130	 */
131	export function isValidVatIdFormat(vatId: string | null | undefined, country: string): boolean {
132	  const id = (vatId ?? "").replace(/\s+/g, "").toUpperCase();
133	  const c = normalizeCountry(country);
134	  if (!c || id.length < 4) return false;
135	  // The VAT id's own country prefix (Greece files under "EL", not "GR").
136	  const prefix = c === "GR" ? "EL" : c;
137	  return new RegExp(`^${prefix}[0-9A-Z]{2,12}$`).test(id);
138	}
139	
140	/** The seller's own country (ISO-3166 alpha-2), from the `seller_country` Setting. */
141	export async function sellerCountry(): Promise<string> {
142	  return normalizeCountry(await getSetting("seller_country"));
143	}
144	
145	export type TaxContext = {
146	  /** The rate actually applied to the net, in percent. */
147	  ratePercent: number;
148	  /** The destination country the rate was resolved for ("" when unknown). */
149	  country: string;
150	  /** True when a valid EU cross-border VAT id zero-rated this as a reverse charge. */
151	  reverseCharged: boolean;
152	};
153	
154	/**
155	 * Resolve the VAT/GST rate to CHARGE for a customer, from their billing country and
156	 * (optional) VAT id. Pure decision logic — the seller country and the global
157	 * fallback rate are passed in so this stays testable and callers resolve settings
158	 * once.
159	 *
160	 *   1. Unknown country                       → the global `tax_percent` fallback.
161	 *   2. Valid VAT id, EU country ≠ seller EU  → 0% (standard B2B reverse charge).
162	 *   3. Known country in the rate table       → that country's standard rate.
163	 *   4. Known country, no table entry         → the global `tax_percent` fallback.
164	 *
165	 * "When in doubt, charge the destination-country consumer rate" — a malformed VAT id
166	 * never reaches case 2 (isValidVatIdFormat gates it), so it lands on case 3.
167	 */
168	export function resolveCountryTaxRate(opts: {
169	  country: string | null | undefined;
170	  vatId?: string | null;
171	  sellerCountry: string;
172	  fallbackPercent: number;
173	}): TaxContext {
174	  const country = normalizeCountry(opts.country);
175	  const fallback = Number.isFinite(opts.fallbackPercent) && opts.fallbackPercent > 0 ? opts.fallbackPercent : 0;
176	  if (!country) return { ratePercent: fallback, country: "", reverseCharged: false };
177	
178	  // B2B reverse charge: a VAT-registered business in a DIFFERENT EU country pays 0%
179	  // and self-accounts for the VAT. Same-country B2B is still charged local VAT.
180	  const seller = normalizeCountry(opts.sellerCountry);
181	  if (
182	    EU_COUNTRIES.has(country) &&
183	    country !== seller &&
184	    isValidVatIdFormat(opts.vatId, country)
185	  ) {
186	    return { ratePercent: 0, country, reverseCharged: true };
187	  }
188	
189	  const table = COUNTRY_VAT_RATES[country];
190	  if (typeof table === "number") return { ratePercent: table, country, reverseCharged: false };
191	  return { ratePercent: fallback, country, reverseCharged: false };
192	}
193	
194	/**
195	 * Resolve the tax context for a specific customer (reads seller country + the global
196	 * fallback rate from Settings once). The single async entry point every charge site
197	 * uses so the rate is derived identically everywhere.
198	 */
199	export async function taxContextForUser(
200	  user: { billingCountry?: string | null; vatId?: string | null },
201	): Promise<TaxContext> {
202	  const [seller, fallback] = await Promise.all([sellerCountry(), taxRate()]);
203	  return resolveCountryTaxRate({
204	    country: user.billingCountry ?? null,
205	    vatId: user.vatId ?? null,
206	    sellerCountry: seller,
207	    fallbackPercent: fallback,
208	  });
209	}
210	
211	/** The tax in cents to ADD to a net service charge at a resolved rate. Integer cents. */
212	export function taxCentsFor(netCents: number, ctx: Pick<TaxContext, "ratePercent">): number {
213	  return applyTax(netCents, ctx.ratePercent).tax;
214	}
