409	  const prices = { ...ctx.prices, taxRatePercent: taxCtx.ratePercent };
410	  const charge = renewalCharge(server, prices);
411	  const renewCents = charge.totalCents;
412	  const base = new Date(Math.max(server.expiresAt!.getTime(), now.getTime()));
413	  const newExpiry = addMonths(base, charge.months);
414	
415	  await clearStaleDunning(server);
416	
417	  let renewed = false;
418	  if (server.autoRenew) {
419	    // `server.user.balanceCents` came from a snapshot taken before this loop and
