424	    const fresh = await db.user.findUnique({
425	      where: { id: server.userId },
426	      select: { balanceCents: true },
427	    });
428	    const split = walletSplit({
429	      dueCents: renewCents,
430	      balanceCents: fresh?.balanceCents ?? 0,
