/* The plan-card promo badge's percent — the REAL gap between the intro monthly
 * rate and the regular monthly rate, so "X% off" can never show a number a
 * plan doesn't actually carry. Computed here (once, server-side) rather than
 * in the card component, same discipline as every other price on this page:
 * the view prints, it does not work anything out. Null (no badge) unless
 * `introCents` is a genuine, positive discount off `regularCents`. */
function introBadgePercent(regularCents: number, introCents: number | null): number | null {
  if (introCents == null || regularCents <= 0 || introCents >= regularCents) return null;
  return Math.max(1, Math.min(99, Math.round((1 - introCents / regularCents) * 100)));
}

