584	  // `let`: a first-month-free hold lost to a concurrent checkout forces a full-price
585	  // re-quote below, which changes the split. Free admin grants skip it entirely.
586	  let { walletApplied, cardCents } = freePath
587	    ? { walletApplied: 0, cardCents: 0 }
588	    : walletSplit({ dueCents: dueWithTax(quote.chargeCents), balanceCents: user.balanceCents, useWallet });
589	
590	  // Card portion is $0 (free admin grant, or the wallet fully covers the charge) →
591	  // provision straight away. placeOrder debits the FULL chargeCents from the wallet
592	  // (or nothing, for a free grant); the balance check inside it holds because a
593	  // $0 card portion means balance >= chargeCents.
594	  if (freePath || cardCents <= 0) {
595	    let serverId: string;
596	    try {
597	      // Reuse the request-scoped IP hash computed above so placeOrder can enforce
598	      // both the coupon's once-per-person guard and the first-month-free 1/IP cap.
599	      serverId = await placeOrder(user, intent, null, { ipHash: promoIpHash, campaign: promoCampaign });
600	    } catch (e) {
601	      if (e instanceof OrderError) return { error: e.message };
602	      throw e;
603	    }
604	    // A wallet-only order is still a real payment (money left the balance) — stamp
605	    // the same `?purchase=1` marker the card/Stripe path gets via reportPurchase, so
606	    // ProvisioningOverlay's "just paid" signal covers this path too. Skip it for a
607	    // free admin grant (freePath): no money moved, nothing to celebrate.
608	    redirect(`/dashboard/servers/${serverId}${freePath ? "" : "?purchase=1"}`);
609	  }
610	
611	  // RESERVE the first-month-free credit BEFORE opening the Checkout session. This is
612	  // the money-race fix: the card leg settles the discounted price up front, so unless
613	  // this account/IP's one credit is held EXCLUSIVELY here, two concurrent card
614	  // checkouts could each pass eligibility and each collect a free month from one
615	  // eligibility. The reserve's INSERT contends on the same two unique constraints as
616	  // the grant, so exactly one checkout holds it; a loser re-quotes at FULL price so
617	  // its stamped total, card leg and settlement all agree (displayed === charged). The
618	  // hold is CONFIRMED at fulfilment, RELEASED on `checkout.session.expired`, and
619	  // swept as a backstop — an abandoned checkout never permanently burns the offer.
620	  //
621	  // `promoCreditCents > 0` is the honest "this quote carries the free month" signal
622	  // (0 whenever the promo is off, already-redeemed via the re-quote above, or the
623	  // product is out of scope — firstMonthFreeAppliesTo). It is 0 for VPS today, so
624	  // this block is inert for VPS and correct the moment the owner extends the promo to
625	  // any card-checkout product.
626	  let promoReservationToken: string | null = null;
627	  if (quote.promoCreditCents > 0) {
628	    const reservedUntil = new Date(Date.now() + ORDER_CHECKOUT_EXPIRES_MS + RESERVATION_GRACE_MS);
629	    const res = await reserveFirstMonthFree({
630	      userId: user.id,
631	      ipHash: promoIpHash,
632	      serviceType: "VPS",
633	      campaign: promoCampaign,
634	      chargedCents: quote.chargeCents,
635	      reservedUntil,
636	    });
637	    if (res.reserved) {
638	      promoReservationToken = res.token;
639	    } else {
640	      // Lost the race (this account/IP already holds or redeemed the credit): re-quote
641	      // at FULL price and recompute the split so the card leg is the real full amount.
642	      quote = await orderQuote(intent, { suppressPromo: true });
643	      ({ walletApplied, cardCents } = walletSplit({ dueCents: dueWithTax(quote.chargeCents), balanceCents: user.balanceCents, useWallet }));
644	      // A full-price re-quote can be fully wallet-covered — provision immediately (its
645	      // own atomic claim inside placeOrder will correctly charge full on a lost claim).
646	      if (cardCents <= 0) {
647	        let serverId: string;
648	        try {
649	          serverId = await placeOrder(user, intent, null, { ipHash: promoIpHash, campaign: promoCampaign });
650	        } catch (e) {
651	          if (e instanceof OrderError) return { error: e.message };
652	          throw e;
653	        }
654	        redirect(`/dashboard/servers/${serverId}?purchase=1`);
655	      }
656	    }
657	  }
658	
659	  // RESERVE the checkout coupon BEFORE opening the Checkout session — the money-race fix
660	  // (Finding 1). The card leg settles the DISCOUNTED price up front, so unless this
661	  // account/IP's slot (the two @@unique constraints) AND a global-cap slot
662	  // (`timesRedeemed` vs `maxRedemptions`) are held EXCLUSIVELY here, N concurrent card
663	  // checkouts could each pass an advisory read and each collect the discount while only
664	  // ONE redemption is recorded — defeating one-per-person/IP AND maxRedemptions. The
665	  // reserve's atomic increment + guarded INSERT means exactly one checkout holds it; a
666	  // loser DROPS the coupon and re-quotes at FULL price so the stamped total, card leg and
667	  // settlement all agree (never a discounted leg without a backing hold — displayed ===
668	  // charged). The hold is CONFIRMED at fulfilment, RELEASED on `checkout.session.expired`,
669	  // and swept as a backstop, so an abandoned checkout never permanently burns the coupon.
670	  //
671	  // Reached only on the TRUE card path (cardCents > 0 at this point): the free-admin and
672	  // wallet-covers-the-total paths above provision immediately via placeOrder, whose OWN
673	  // atomic `claimOrderCoupon` handles the coupon — so a coupon is never both reserved here
674	  // and claimed there. `promoIpHash` is the same request IP the promo reserve used, already
675	  // null-normalised (an empty string would collide across every IP-less redemption).
676	  let checkoutIntent = intent;
677	  let couponReservationToken: string | null = null;
678	  if (quote.couponId && quote.couponDiscountCents > 0) {
679	    const reservedUntil = new Date(Date.now() + ORDER_CHECKOUT_EXPIRES_MS + RESERVATION_GRACE_MS);
680	    const res = await reserveOrderCoupon({
681	      couponId: quote.couponId,
682	      maxRedemptions: quote.couponMaxRedemptions,
683	      firstTimeOnly: quote.couponFirstTimeOnly,
684	      excludeActiveCustomers: quote.couponExcludeActiveCustomers,
685	      userId: user.id,
686	      ipHash: promoIpHash,
687	      amountCents: quote.couponDiscountCents,
688	      reservedUntil,
689	    });
690	    if (res.reserved) {
691	      couponReservationToken = res.token;
692	    } else {
693	      // Lost the exclusive hold: drop the coupon and re-quote at FULL price, then recompute
694	      // the split. Full price can only be >= the discounted one, so the card leg stays > 0
695	      // (no immediate-provision path to re-enter). Preserve the current promo state — keep a
696	      // promo hold if one was taken, otherwise suppress (promo off / ineligible / N/A here).
697	      checkoutIntent = { ...intent, couponCode: undefined };
698	      quote = await orderQuote(checkoutIntent, { suppressPromo: !promoReservationToken });
699	      ({ walletApplied, cardCents } = walletSplit({ dueCents: dueWithTax(quote.chargeCents), balanceCents: user.balanceCents, useWallet }));
700	    }
701	  }
702	
703	  // Card portion > 0 → charge ONLY the remainder on the card (not the full total).
704	  // On payment success the confirm route credits this card amount to the wallet and
705	  // then placeOrder debits the full chargeCents, so the wallet naturally absorbs
706	  // `walletApplied` and the card the rest — the wallet is never touched before the
707	  // card clears. (walletApplied is implied by cardCents vs. the recomputed charge,
708	  // so it needs no separate metadata field.)
709	  // The price is handed over EXPLICITLY, from the very quote the wallet split above
710	  // was computed from. Without this argument `createOrderCheckout` re-quotes
711	  // internally, microseconds later, from its own `new Date()` — the same function,
712	  // so no formula can drift, but two different instants. A promo boundary (or an
713	  // operator changing a plan price) falling between them would mean the card leg
714	  // and the stamped total were priced against two different worlds, and the wallet
715	  // would silently absorb the difference. One quote, one price, one charge.
716	  // If opening the session fails after we reserved, RELEASE both holds so the customer
717	  // never loses their offer (or the coupon's slot) to a checkout that never came into being.
718	  // `checkoutIntent` — not `intent` — so a coupon dropped on a lost reserve above is also
719	  // absent from the metadata fulfilment re-quotes from, matching the full-price `sold`.
720	  let checkout: EmbeddedCheckout | null;
721	  try {
722	    // Custom Checkout (ui_mode: "elements"), not the old embedded_page modal — the
723	    // card leg of the new embedded Payment step (components/customer/PaymentStep.tsx).
724	    // Identical params/metadata/promo-and-coupon-hold handling to
725	    // `createOrderCheckout`; see lib/stripe.ts's doc comment on why this is a pure
726	    // presentation change with zero fulfilment-path impact.
727	    checkout = await createOrderPaymentSession(
728	      user,
729	      cardCents,
730	      checkoutIntent,
731	      // Stamp the VAT the card leg was split from so fulfilment settles the SAME
732	      // tax-inclusive total — never re-derived after the card cleared.
733	      orderPriceOf(quote, { taxCents: taxOn(quote.chargeCents), ratePercent: taxCtx.ratePercent, country: taxCtx.country }),
734	      promoCampaign,
735	      promoReservationToken,
736	      couponReservationToken,
737	    );
738	  } catch (e) {
739	    if (promoReservationToken) await releaseReservation(promoReservationToken).catch(() => {});
740	    if (couponReservationToken) await releaseOrderCouponReservation(couponReservationToken).catch(() => {});
741	    throw e;
742	  }
743	  if (!checkout) {
744	    if (promoReservationToken) await releaseReservation(promoReservationToken).catch(() => {});
745	    if (couponReservationToken) await releaseOrderCouponReservation(couponReservationToken).catch(() => {});
746	    return { error: "Card payments aren't set up yet — top up your wallet to deploy." };
747	  }
748	  // The embedded session (clientSecret + publishableKey) for the modal on our page.
749	  return { checkout };
750	}
