754	async function ownedServer(serverId: string) {
755	  const user = await requireUser();
756	  const server = await db.server.findUnique({ where: { id: serverId } });
757	  if (!server) throw new Error("Not found");
758	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
759	  return { user, server };
760	}
761	
762	export async function serverAction(serverId: string, action: string): Promise<{ error?: string } | void> {
763	  // Returns `{ error }` for anything the CUSTOMER can act on, so ServerControls
764	  // can render it — a `throw` here reaches the browser as Next's redacted generic
765	  // error, discarding the specific, actionable message (e.g. "Delete your data
766	  // volume(s) before reinstalling"). Only genuinely-impossible states still throw.
767	  const { user, server } = await ownedServer(serverId);
768	  const allowed: Record<string, "START" | "STOP" | "REBOOT" | "REINSTALL" | "DELETE"> = {
769	    start: "START",
770	    stop: "STOP",
771	    reboot: "REBOOT",
772	    reinstall: "REINSTALL",
773	    delete: "DELETE",
774	  };
775	  const type = allowed[action];
776	  if (!type) throw new Error("Invalid action"); // not reachable from the UI — a real bug if it happens
777	  if (server.status === "SUSPENDED" && user.role !== "ADMIN") {
778	    return { error: "This server is suspended. Settle the outstanding balance to control it again." };
779	  }
780	
781	  // A reinstall wipes the whole VM, including any block-storage volume the VM
782	  // owns (Proxmox `qm destroy --purge` frees every disk for that vmid).
783	  //
784	  // Count volumes by `serverId` ALONE, never by `status: "ATTACHED"`. Detaching
785	  // deliberately keeps `serverId` set so the volume can be re-attached
786	  // (worker/volumes.ts) — the disk stays owned by this vmid as an `unusedN`
787	  // entry, and PVE's destroy_vm frees unused disks too (include_unused => 1).
788	  // Filtering on ATTACHED therefore missed the worst case: customer fills a
789	  // volume, clicks Detach (the UI promises "Data is preserved."), clicks
790	  // Reinstall — both guards see zero attached volumes, and the purge takes the
791	  // data with it. `reinstallToOs` in actions-server-lifecycle.ts always counted
792	  // by serverId; this path did not. That asymmetry was the bug.
793	  if (type === "REINSTALL") {
794	    const pinnedVolumes = await db.volume.count({ where: { serverId } });
795	    if (pinnedVolumes > 0) {
796	      return {
797	        error:
798	          "Delete your data volume(s) before reinstalling — a reinstall wipes the whole server, and that includes detached volumes still assigned to it. Open Volumes first.",
799	      };
800	    }
801	  }
802	
803	  const pending = await db.job.count({
804	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
805	  });
806	  // Was a silent `return`: the customer clicked Start and nothing happened, ever,
807	  // with no explanation. Tell them why.
808	  if (pending > 0) return { error: "Another operation is already running on this server. Wait for it to finish." };
809	
810	  if (type === "DELETE") {
811	    await db.server.update({ where: { id: serverId }, data: { status: "DELETING" } });
812	  }
813	  await db.job.create({ data: { type, serverId } });
814	  await audit(user.id, `server.${action}`, serverId);
815	  if (type === "DELETE") redirect(user.role === "ADMIN" ? "/admin/servers" : "/dashboard");
816	  revalidatePath(`/dashboard/servers/${serverId}`);
817	}
