660	export async function placeOrder(
661	  user: User,
662	  intent: OrderIntent,
663	  sold?: OrderPrice | null,
664	  opts?: {
665	    ipHash?: string | null;
666	    campaign?: string;
667	    promoReservationToken?: string | null;
668	    couponReservationToken?: string | null;
669	  },
670	): Promise<string> {
671	  const quote = await orderQuote(intent);
672	  const { plan, os, term, promo, promoCreditCents, extraDiskGB, extraDiskMonthlyCents, extraDiskCents, backupTier, backupMonthlyCents, backupCents, ipCents } = quote;
673	  // Everything below bills off THESE three, never off `quote.chargeCents` /
674	  // `promo` directly: when a sold price is present it is the whole truth about
675	  // what this order costs and what rate it was sold at.
676	  const chargeCents = sold?.chargeCents ?? quote.chargeCents;
677	  const promoPercent = sold?.promoPercent ?? promo.discountPercent;
678	  const promoName = sold?.promoName || promo.name;
679	
680	  // Managed first-month-free — how this order settles the credit depends on the path:
681	  //   WALLET path (no `sold`): the credit rides on the fresh quote (promoCreditCents
682	  //     > 0), and we contend for it with an atomic INSERT inside the charge tx below.
683	  //   CARD/Stripe path (`sold` present): the credit was already RESERVED before the
684	  //     card was charged, and its hold token travels in `opts.promoReservationToken`.
685	  //     We CONFIRM that hold (never a fresh contended INSERT) — that is what closes
686	  //     the double-claim race. No token => this order was sold at FULL price, so there
687	  //     is nothing to grant. We deliberately do NOT infer the credit from
688	  //     `sold.promoPercent` (currentPromo always stamps 100, even on a full-price VPS
689	  //     order), which would record a redemption for a purchase that never got one.
690	  const walletPromoApplied = !sold && promoCreditCents > 0;
691	  const cardPromoToken = sold ? opts?.promoReservationToken ?? null : null;
692	  // Note the intro discount on the billing document (first term only; renews full) —
693	  // ONLY when this specific order actually earned the credit (real customer report:
694	  // a full-price $8.88 VPS invoice read "First month free · 100% off first term",
695	  // because `promo.discountPercent` is a raw, ALWAYS-100 constant — see the comment
696	  // above — and this used to gate on that instead of on whether the credit was
697	  // actually granted to THIS order, same signal walletPromoApplied/cardPromoToken
698	  // already use to decide whether to grant it).
699	  const promoNote = walletPromoApplied || cardPromoToken ? ` · ${promoName} ${promoPercent}% off first term` : "";
700	  // The checkout coupon settles the same two ways:
701	  //   WALLET path (no `sold`): atomic claim in its OWN tx below (claimOrderCoupon), which
702	  //     throws and surfaces before any money moves if the last slot just went.
703	  //   CARD/Stripe path (`sold`): the coupon was RESERVED before the card was charged and
704	  //     its hold token travels in `opts.couponReservationToken`. We CONFIRM that hold
705	  //     inside the charge tx (never a fresh contended claim — that would double-count the
706	  //     global cap and collide on the per-person unique). No token => full-price order.
707	  const cardCouponToken = sold ? opts?.couponReservationToken ?? null : null;
708	
709	  const cap = await capacityCheck(plan.id);
710	  if (!cap.ok) throw new OrderError(cap.reason);
711	
712	  let nodeId: string | null = null;
713	  if (intent.nodeId) {
714	    const n = await db.node.findFirst({ where: { id: intent.nodeId, enabled: true } });
715	    if (!n) throw new OrderError("Selected location is not available.");
716	    nodeId = n.id;
717	  } else if (intent.region) {
718	    // Customer picked a region, not a specific node — resolve the actual
719	    // node NOW (least loaded within that region), not from whatever the
720	    // wizard page happened to load. See OrderIntent.region's own comment.
721	    const n = await scheduleNode(plan.ramMB, { region: intent.region, provider: intent.provider });
722	    if (!n) throw new OrderError("That location is at capacity right now — please pick another.");
