724	  } else {
725	    const n = await scheduleNode(plan.ramMB);
726	    nodeId = n?.id ?? null;
727	  }
728	
729	  // Reserve the EFFECTIVE size (plan + upsold extra) — the VM really is that big.
730	  const diskCap = await diskCapacityCheck(nodeId, effectiveDiskGB(plan.diskGB, extraDiskGB));
731	  if (!diskCap.ok) throw new OrderError(diskCap.reason);
732	
733	  const addons = {
734	    malwareScanner: !!intent.addonMalware,
735	    dailyBackup: !!intent.addonBackup,
736	    docker: !!intent.addonDocker,
