765	  // OrderError so the deploy action shows the message verbatim.
766	  if (!freeRequested) {
767	    try {
768	      await assertSpendCap(user, chargeCents + orderTaxCents);
769	    } catch (e) {
770	      if (e instanceof SpendCapError) throw new OrderError(e.message);
771	      throw e;
772	    }
773	  }
774	
775	  // WALLET path ONLY: claim the coupon atomically BEFORE the order tx, so a wallet order
776	  // fails cleanly (no money moved) if the last slot just went. A free admin grant never
777	  // consumes a customer coupon. The CARD path does NOT claim here — it reserved the coupon
