782	      couponId: quote.couponId,
783	      maxRedemptions: quote.couponMaxRedemptions,
784	      firstTimeOnly: quote.couponFirstTimeOnly,
785	      excludeActiveCustomers: quote.couponExcludeActiveCustomers,
786	      userId: user.id,
787	      ipHash: opts?.ipHash ?? null,
788	      amountCents: quote.couponDiscountCents,
789	    });
790	  }
791	
792	  const newKey = (intent.sshPublicKey ?? "").trim();
793	  const keyName = (intent.sshKeyName ?? "deploy-key").slice(0, 60);
794	
795	  let server;
796	  // Captured from the in-tx invoice.create so the paid ORDER invoice can be emailed
797	  // (with its PDF) AFTER the transaction commits — a rolled-back order leaves this
798	  // null and emails nothing. Only paid orders create an invoice (free admin grants
799	  // skip the `if (!freeRequested)` block below), so this stays null for those.
800	  let orderInvoice: { id: string; number: number; amountCents: number; description: string } | null = null;
