802	    server = await db.$transaction(async (tx) => {
803	      // ATOMIC first-month-free claim, INSIDE the charge tx (mirrors claimOrderCoupon).
804	      // Contend for the redemption BEFORE debiting so the debit amount matches the
805	      // outcome. A lost claim never throws — on the wallet path we add the credit
806	      // back and charge FULL; on the card path the money already settled at the sold
807	      // price (screened by the pre-checkout guard in actions.ts), so we keep it and
808	      // record nothing — the same swallow discipline the coupon path uses.
809	      let debitCents = chargeCents;
810	      let promoNoteFinal = promoNote;
811	      let promoClaimId: string | null = null;
812	      let soldFull = false; // wallet order that lost the claim and paid full price
813	      if (!freeRequested && cardPromoToken) {
814	        // CARD/Stripe path: confirm the hold reserved before the card was charged.
815	        // The card already settled at the sold (discounted) price; confirming just
816	        // flips the hold to CONSUMED and anchors it. NEVER a second debit here.
817	        const confirmed = await confirmReservation(tx, cardPromoToken);
