822	          // leg. This is unreachable while the hold outlives the payable session, but
823	          // if it ever happens we must NOT charge more than the customer was shown.
824	          // Try to record the grant so a later renewal can convert it; if even that
825	          // loses (the slot is now another order's), keep the discounted charge and
826	          // log — the same swallow discipline the paid-coupon path uses.
827	          const fallback = await claimFirstMonthFree(tx, {
828	            userId: user.id,
829	            ipHash: opts?.ipHash ?? null,
830	            serviceType: "VPS",
831	            campaign: opts?.campaign ?? "",
832	            chargedCents: chargeCents,
