import { NextRequest, NextResponse } from "next/server";
import { paypalConfigured, verifyPayPalWebhookSignature, getPayPalOrder, vaultInfoFromCapture } from "@/lib/paypal";
import { fulfilExternalPayment } from "@/lib/fulfil-checkout";
import { db } from "@/lib/db";

/**
 * PayPal's reliable backstop, the same role app/api/stripe/webhook/route.ts plays
 * for Stripe: the client-driven capture (lib/actions-payment-providers.ts's
 * `captureExternalPayPalOrder`, called from the wizard's `onApprove`) may never
 * run at all if the customer closes the tab right after approving — this is the
 * ONLY guaranteed-to-fire signal in that case.
 *
 * Signature verification is PayPal's own server-to-server
 * `/v1/notifications/verify-webhook-signature` call (see lib/paypal.ts) — no local
 * certificate-chain validation to get subtly wrong. A webhook that cannot be
 * PROVEN authentic is rejected with 400, never processed "just in case".
 *
 * Idempotent the same way the Stripe webhook is: `fulfilExternalPayment` claims
 * a `FulfilledSession` row keyed `paypal:<orderId>` before doing any provisioning,
 * so this racing the client-driven capture (or PayPal redelivering the same
 * event) is always safe.
 */
export async function POST(req: NextRequest) {
  if (!paypalConfigured()) {
    return NextResponse.json({ error: "not configured" }, { status: 400 });
  }
  const raw = await req.text();

  const verified = await verifyPayPalWebhookSignature(req.headers, raw);
  if (!verified) {
    return NextResponse.json({ error: "invalid signature" }, { status: 400 });
  }

  let event: { event_type?: string; resource?: { id?: string; supplementary_data?: { related_ids?: { order_id?: string } } } };
  try {
    event = JSON.parse(raw);
  } catch {
    return NextResponse.json({ error: "invalid payload" }, { status: 400 });
  }

  // We only need to act on a completed capture. `CHECKOUT.ORDER.APPROVED` fires
  // before the money moves — fulfilling on it would be exactly the "browser
  // signal, not a payment signal" mistake this codebase's Stripe fulfilment
  // comments document at length. `PAYMENT.CAPTURE.COMPLETED` is the money-moved
  // event; its resource is the CAPTURE, so the order id is recovered from
  // `supplementary_data.related_ids.order_id` (PayPal's documented shape) rather
  // than assumed to be `resource.id`.
  if (event.event_type === "PAYMENT.CAPTURE.COMPLETED") {
    const orderId = event.resource?.supplementary_data?.related_ids?.order_id;
    if (!orderId) {
      console.error("[paypal-webhook] capture event carried no order id", event.resource?.id);
      return NextResponse.json({ received: true });
    }
    try {
      // Re-derive the pendingId the same way the client-driven capture does: the
      // order's own custom_id (set at creation time in openPayPal). A defence-in-
      // depth re-read from PayPal itself, never trusting the webhook payload's own
      // (unsigned-at-this-layer) resource fields for anything but the order id.
      const order = await getPayPalOrder(orderId);
      const pendingId = order.purchase_units?.[0]?.custom_id;
      if (!pendingId) {
        console.error("[paypal-webhook] order carried no custom_id", orderId);
        return NextResponse.json({ received: true });
      }
      const row = await db.pendingExternalPayment.findUnique({ where: { id: pendingId } });
      if (!row) {
        console.error("[paypal-webhook] no PendingExternalPayment for", pendingId);
        return NextResponse.json({ received: true });
      }
      // Closed-tab backstop for the vault save too — mirrors the same
      // best-effort, non-fatal write captureExternalPayPalOrder does for the
      // client-driven path (lib/actions-payment-providers.ts).
      const vault = vaultInfoFromCapture(order);
      if (vault) {
        await db.user
          .update({ where: { id: row.userId }, data: { paypalVaultId: vault.vaultId, paypalPayerEmail: vault.payerEmail } })
          .catch((e) => console.error("[paypal-webhook] could not record vaulted PayPal method", e));
      }
      await fulfilExternalPayment({ provider: "paypal", externalId: orderId, pendingId, base: process.env.APP_URL ?? "" });
    } catch (e) {
      // Errors are swallowed deliberately, exactly like the Stripe webhook: a
      // non-2xx here makes PayPal retry, and the failure is already recorded on
      // the FulfilledSession row and surfaced to the customer via notifyStalled.
      console.error("[paypal-webhook] fulfil failed", orderId, e);
    }
  }

  return NextResponse.json({ received: true });
}
