import { requireUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { getSettingInt } from "@/lib/settings";
import { generateReferralCode } from "@/lib/growth";
import { rankFor, tierFor } from "@/lib/nx/rewards";
import { RewardsView } from "@/components/nx/RewardsView";

/* Refer & earn + the partner programme, on ONE page.
 *
 * They were two routes — /refer and /affiliate — describing the same thing to
 * the same person in two different vocabularies, plus /partner for the agency
 * side. This is the customer-facing half of the concept's Affiliates screen,
 * with the partner half shown only to an account that actually IS one.
 *
 * EVERY FIGURE HERE IS REAL. The concept's "10% shared hosting / 5% VPS" cards
 * are NOT reproduced: this platform pays a FLAT per-referral credit
 * (`referral_reward_cents`, $5 by default) and percentage commission exists only
 * on the partner side (`ReferralPartner.commissionRatePct`). Printing the
 * percentages would advertise a scheme the money code does not run.
 */

async function ensureReferralCode(userId: string, current: string | null): Promise<string> {
  if (current) return current;
  for (let i = 0; i < 6; i++) {
    const code = generateReferralCode();
    if (await db.user.findUnique({ where: { referralCode: code } })) continue;
    try {
      await db.user.update({ where: { id: userId }, data: { referralCode: code } });
      return code;
    } catch { /* unique clash race — retry */ }
  }
  const fallback = generateReferralCode(12);
  await db.user.update({ where: { id: userId }, data: { referralCode: fallback } });
  return fallback;
}

export default async function ReferPage() {
  const user = await requireUser();
  const code = await ensureReferralCode(user.id, user.referralCode);
  const rewardCents = await getSettingInt("referral_reward_cents", 500);

  const monthAgo = new Date(Date.now() - 30 * 86_400_000);
  const twoMonthsAgo = new Date(Date.now() - 60 * 86_400_000);

  const [total, rewarded, thisMonth, lastMonth, clicks, convertedClicks, partner, recent] =
    await Promise.all([
      db.user.count({ where: { referredById: user.id } }),
      db.user.count({ where: { referredById: user.id, referralRewardedAt: { not: null } } }),
      db.user.count({ where: { referredById: user.id, createdAt: { gte: monthAgo } } }),
      db.user.count({ where: { referredById: user.id, createdAt: { gte: twoMonthsAgo, lt: monthAgo } } }),
      /* The denominator for a conversion rate. Zero until the link is clicked —
         and a rate on zero clicks is shown as "—", never as 0%. */
      db.referralClick.count({ where: { code } }),
      db.referralClick.count({ where: { code, convertedUserId: { not: null } } }),
      db.referralPartner.findUnique({ where: { userId: user.id } }).catch(() => null),
      db.user.findMany({
        where: { referredById: user.id },
        select: { email: true, name: true, createdAt: true, referralRewardedAt: true },
        orderBy: { createdAt: "desc" },
        take: 8,
      }),
    ]);

  const { current, next } = rankFor(rewarded);

  /* Six monthly buckets of signups and credit, oldest first, zero-filled. The
     sparklines draw THIS — a chart on invented numbers is a lie with a trend
     line through it. `allReferrals` is already fetched above for the list. */
  const series: { signups: number[]; credit: number[] } = { signups: [], credit: [] };
  {
    const now = new Date();
    const rows = await db.user.findMany({
      where: { referredById: user.id, createdAt: { gte: new Date(now.getFullYear(), now.getMonth() - 5, 1) } },
      select: { createdAt: true, referralRewardedAt: true },
    });
    for (let i = 5; i >= 0; i--) { series.signups.push(0); series.credit.push(0); }
    for (const r of rows) {
      const idx = (r.createdAt.getFullYear() - now.getFullYear()) * 12
                + (r.createdAt.getMonth() - now.getMonth()) + 5;
      if (idx < 0 || idx > 5) continue;
      series.signups[idx] += 1;
      if (r.referralRewardedAt) series.credit[idx] += rewardCents;
    }
  }

  return (
    <RewardsView
      code={code}
      link={`${process.env.APP_URL ?? "https://nxeon.cloud"}/r/${code}`}
      rewardCents={rewardCents}
      total={total}
      rewarded={rewarded}
      thisMonth={thisMonth}
      lastMonth={lastMonth}
      clicks={clicks}
      convertedClicks={convertedClicks}
      rank={current}
      series={series}
      nextRank={next}
      /* Earned is what has ACTUALLY been credited: the flat reward times the
         referrals that reached the rewarded state. Pending is the rest — signed
         up, not yet qualified — and is labelled as such rather than counted. */
      earnedCents={rewarded * rewardCents}
      pendingCents={Math.max(0, total - rewarded) * rewardCents}
      recent={recent.map((r) => ({
        name: r.name || r.email.split("@")[0],
        email: r.email,
        joined: r.createdAt.toISOString(),
        rewarded: !!r.referralRewardedAt,
      }))}
      partner={partner ? {
        name: partner.name,
        code: partner.code,
        ratePct: partner.commissionRatePct,
        tier: tierFor(partner.commissionRatePct).name,
        type: partner.type ?? null,
        status: partner.status,
        link: `${process.env.APP_URL ?? "https://nxeon.cloud"}/partner/${partner.code}`,
      } : null}
    />
  );
}
