/* Referral ranks and partner tiers.
 *
 * Both ladders are DERIVED, not stored: a rank is a function of how many
 * referrals converted, a tier is a function of the commission rate already on
 * the partner record. Storing either would create a second source of truth that
 * drifts the moment a referral is refunded or a rate is changed in admin.
 *
 * The ladder names come from the icon pack the owner supplied (Bronze, Silver,
 * Gold, Platinum, Diamond, Titan, Apex). The THRESHOLDS are a first pass and
 * are the one part of this file that is a product decision rather than a fact —
 * they are here, in one list, so they can be tuned without hunting through JSX.
 */

export type Rank = {
  key: string;
  name: string;
  /** Converted referrals needed to reach this rank. */
  at: number;
  /** Ring colour for the badge. */
  tone: string;
};

export const RANKS: Rank[] = [
  { key: "bronze",   name: "Bronze",   at: 0,   tone: "#c08457" },
  { key: "silver",   name: "Silver",   at: 3,   tone: "#b9c4d6" },
  { key: "gold",     name: "Gold",     at: 10,  tone: "#f2b544" },
  { key: "platinum", name: "Platinum", at: 25,  tone: "#7f9fe8" },
  { key: "diamond",  name: "Diamond",  at: 50,  tone: "#5fd0ff" },
  { key: "titan",    name: "Titan",    at: 100, tone: "#a855f7" },
  { key: "apex",     name: "Apex",     at: 250, tone: "#f21cff" },
];

/** The rank a referral count sits in, and the next one up (null at the top). */
export function rankFor(referrals: number): { current: Rank; next: Rank | null } {
  let current = RANKS[0];
  for (const r of RANKS) if (referrals >= r.at) current = r;
  const next = RANKS[RANKS.indexOf(current) + 1] ?? null;
  return { current, next };
}

/* ── partner tiers ──────────────────────────────────────────────────────
   Read off `ReferralPartner.commissionRatePct`, which is what the money
   actually uses. A partner on a negotiated rate falls through to Custom
   rather than being squeezed into the nearest named tier. */
export type Tier = { key: string; name: string; ratePct: number | null; blurb: string; perks: string[] };

export const TIERS: Tier[] = [
  { key: "starter", name: "Starter", ratePct: 10, blurb: "Ideal for individuals",
    perks: ["All products included", "No minimum required", "Paid on every renewal"] },
  { key: "growth", name: "Growth", ratePct: 15, blurb: "For active creators",
    perks: ["Higher volume rewards", "Priority support", "Paid on every renewal"] },
  { key: "pro", name: "Pro", ratePct: 20, blurb: "For agencies & communities",
    perks: ["Custom marketing support", "Early access to new products", "Paid on every renewal"] },
  { key: "custom", name: "Custom", ratePct: null, blurb: "For large partners",
    perks: ["Custom rates & incentives", "Dedicated account manager", "Negotiated terms"] },
];

export function tierFor(ratePct: number | null | undefined): Tier {
  const exact = TIERS.find((t) => t.ratePct !== null && t.ratePct === ratePct);
  return exact ?? TIERS[TIERS.length - 1];
}

